import{_ as i,C as h,o,c as l,a2 as d,b as r,w as t,a as s,E as c,a3 as n}from"./chunks/framework.Dg5fKO7V.js";const k=JSON.parse('{"title":"Architecture Boundaries","description":"","frontmatter":{},"headers":[],"relativePath":"Architecture-Boundaries.md","filePath":"Architecture-Boundaries.md","lastUpdated":1788563284000}'),p={name:"Architecture-Boundaries.md"};function u(m,e,f,b,g,y){const a=h("Mermaid");return o(),l("div",null,[e[2]||(e[2]=d(`<h1 id="architecture-boundaries" tabindex="-1">Architecture Boundaries <a class="header-anchor" href="#architecture-boundaries" aria-label="Permalink to &quot;Architecture Boundaries&quot;">​</a></h1><p>This page answers one question: where does the next thing go. It describes the structure that is actually in the repository, and every rule on it is enforced either by <code>eslint.config.js</code> or by the project checks imported into Sonar. A rule nobody checks is a rule that stops being true, so if you change a boundary, change its check in the same commit.</p><p>See also <a href="./Architecture-Overview">Architecture Overview</a>, <a href="./Architecture-Backend">Architecture Backend</a>, <a href="./Providers-Reference">Providers Reference</a> and <a href="./Data-Sources">Data Sources</a>.</p><hr><h2 id="the-two-halves" tabindex="-1">The two halves <a class="header-anchor" href="#the-two-halves" aria-label="Permalink to &quot;The two halves&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/          the interface, SolidJS + TypeScript</span></span>
<span class="line"><span>src-tauri/    the backend, Rust</span></span></code></pre></div><p>They meet at exactly one place, the Tauri IPC boundary. On the frontend that is <code>src/shared/ipc/</code>; on the backend it is <code>src-tauri/src/commands/</code>. Nothing else on either side knows a command name.</p><hr><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><h3 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h3>`,10)),(o(),r(n,null,{default:t(()=>[c(a,{id:"mermaid-24",class:"mermaid",graph:"flowchart%20TB%0A%20%20app%20--%3E%20features%20--%3E%20shared%20--%3E%20config%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=d('<p>Imports point downwards only. A file&#39;s folder therefore tells you what it is allowed to reach.</p><table tabindex="0"><thead><tr><th>Layer</th><th>Owns</th><th>May import</th></tr></thead><tbody><tr><td><code>app</code></td><td>booting, the shell, routes, onboarding, shutdown, the global event bridge</td><td>everything below</td></tr><tr><td><code>features</code></td><td>one behaviour each</td><td><code>shared</code>, <code>config</code></td></tr><tr><td><code>shared</code></td><td>what more than one feature needs</td><td><code>shared</code>, <code>config</code></td></tr><tr><td><code>config</code></td><td>named numbers and the reason they have that size</td><td>nothing</td></tr></tbody></table><p><code>shared</code> may not import <code>features</code> or <code>app</code>. <code>features</code> may not import <code>app</code>. <code>config</code> imports nothing at all, which is what makes it safe to read from anywhere.</p><h3 id="inside-a-feature" tabindex="-1">Inside a feature <a class="header-anchor" href="#inside-a-feature" aria-label="Permalink to &quot;Inside a feature&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Folder</th><th>Holds</th></tr></thead><tbody><tr><td><code>model/</code></td><td>Pure decisions</td></tr><tr><td><code>io/</code></td><td>Resources, orchestration, side effects</td></tr><tr><td><code>ui/</code></td><td>SolidJS components</td></tr><tr><td><code>tests/</code></td><td>This feature&#39;s tests</td></tr></tbody></table><p><strong><code>model/</code></strong> is deterministic. Same input, same output, no clock, no network, no storage, no process-wide state, and no idea how its result will be drawn. ESLint blocks it from importing <code>@/shared/ipc</code>, the stateful shared packages, any <code>io/</code>, any <code>ui/</code>, and <code>createResource</code>. This is the part you can test without a DOM, and most of the feature&#39;s real thinking should end up here.</p><p><strong><code>io/</code></strong> owns everything <code>model/</code> is not allowed to touch: Solid resources, IPC calls, timers, listeners, long-lived state. A factory here is named after its lifecycle, <code>createX</code> for something the caller owns and disposes, <code>installX</code> for something that attaches itself for the life of the window. It never renders.</p><p><strong><code>ui/</code></strong> renders state and calls named operations from <code>io/</code>. It does not talk to transport: a component that needs a backend call asks <code>io/</code> for one that has a name. Component files are PascalCase and match the symbol they export.</p><p><strong><code>tests/</code></strong> holds the feature&#39;s tests. There are no colocated <code>*.test.ts</code> files anywhere in <code>src/</code>; the architecture test fails on one.</p><h3 id="what-other-features-may-read" tabindex="-1">What other features may read <a class="header-anchor" href="#what-other-features-may-read" aria-label="Permalink to &quot;What other features may read&quot;">​</a></h3><p>A feature&#39;s <code>model/</code>, <code>io/</code> and <code>ui/</code> are its public surface. Anything else, <code>tests/</code> in particular, is its inside and is not importable from elsewhere.</p><p>Cross-feature imports are allowed but should stay rare and one-directional. The graph has no cycles and the architecture test keeps it that way. When two features start needing the same thing, the answer is usually one of:</p><ol><li>it is a small pure contract → <code>shared/</code></li><li>it belongs to the destination, not the caller → move it there (route warming lives in <code>features/anime/io/warmRoutes.ts</code> for exactly this reason: the anime feature owns the routes being warmed)</li><li>it is composition → <code>app/</code></li></ol><h3 id="the-shared-rule" tabindex="-1">The <code>shared</code> rule <a class="header-anchor" href="#the-shared-rule" aria-label="Permalink to &quot;The `shared` rule&quot;">​</a></h3><blockquote><p>Code belongs in <code>shared</code> only when it is genuinely application-independent, or when more than one independent feature needs it.</p></blockquote><p>Convenience is not a reason. A shared package is named after the capability it provides, never after a layer: there is no <code>shared/utils</code>, <code>shared/helpers</code>, <code>shared/io</code> or <code>shared/model</code>, and the <code>feature-layout</code> Sonar project check reports one.</p><p>The packages, and what each is for:</p><table tabindex="0"><thead><tr><th>Package</th><th>Provides</th></tr></thead><tbody><tr><td><code>anime</code></td><td>what an anime record is and how a card decides to show it</td></tr><tr><td><code>cache</code></td><td>the SWR resource and the one safe way to read a settled one</td></tr><tr><td><code>catalog</code></td><td>the local catalogue&#39;s lifecycle: warmup, refresh, the change signal</td></tr><tr><td><code>colour</code></td><td>contrast and colour-space conversion</td></tr><tr><td><code>easter-egg</code></td><td>the SBR trigger and the brand it leaves on a profile</td></tr><tr><td><code>errors</code></td><td>the error taxonomy shared with <code>src-tauri/src/foundation/error.rs</code></td></tr><tr><td><code>formatting</code></td><td>durations, numbers, text</td></tr><tr><td><code>i18n</code></td><td>the locales and <code>translate()</code></td></tr><tr><td><code>images</code></td><td>proxied URLs, steady loading, the accent sampled from a cover</td></tr><tr><td><code>ipc</code></td><td>the Tauri command surface</td></tr><tr><td><code>keyboard</code></td><td>typing targets and type-to-open</td></tr><tr><td><code>logging</code></td><td>the logger and its redaction</td></tr><tr><td><code>media</code></td><td>HTML media-element handling</td></tr><tr><td><code>network</code></td><td>latency and reachability</td></tr><tr><td><code>notifications</code></td><td>the notification store and its sound</td></tr><tr><td><code>platform</code></td><td>the window, the updater, Discord presence, the engine</td></tr><tr><td><code>preferences</code></td><td>everything persisted about how the app looks and behaves</td></tr><tr><td><code>providers</code></td><td>which streaming sources exist and which are switched off</td></tr><tr><td><code>reactive</code></td><td>small Solid primitives</td></tr><tr><td><code>track</code></td><td>the four sub/dub × en/de tracks and which one an episode opens in</td></tr><tr><td><code>ui</code></td><td>components that work without knowing what an anime is</td></tr></tbody></table><p><code>shared/ui</code> is for components that could be used by an application that has never heard of anime. A component that knows about the player, the library or a download belongs to that feature.</p><p>Two packages publish a deliberate entry point and keep the rest internal: <code>shared/ipc/index.ts</code> and <code>shared/catalog/index.ts</code>. Elsewhere there are no barrels, because a barrel that exists only for tidiness costs tree-shaking and buys nothing.</p><h3 id="shared-ipc" tabindex="-1"><code>shared/ipc</code> <a class="header-anchor" href="#shared-ipc" aria-label="Permalink to &quot;`shared/ipc`&quot;">​</a></h3><p>Every Tauri command name and argument shape in the frontend is written down here, once. <code>invoke()</code> is banned everywhere else, by ESLint, including in components. The path from a click to the backend is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ui  →  feature io  →  shared/ipc  →  Tauri</span></span></code></pre></div><p>The name is <code>ipc</code> and not <code>api</code> on purpose. AniList, Kitsu and the providers are all APIs too. This folder is the boundary to our own Rust process, and nothing else.</p><h3 id="app" tabindex="-1"><code>app</code> <a class="header-anchor" href="#app" aria-label="Permalink to &quot;`app`&quot;">​</a></h3><p><code>app</code> is the composition root and nothing else. It boots the application, owns the shell, composes routes, bridges backend events, runs onboarding, and shuts down. Feature logic does not move up into it, and composition does not move down into <code>shared</code>.</p><hr><h2 id="rust" tabindex="-1">Rust <a class="header-anchor" href="#rust" aria-label="Permalink to &quot;Rust&quot;">​</a></h2><h3 id="flow" tabindex="-1">Flow <a class="header-anchor" href="#flow" aria-label="Permalink to &quot;Flow&quot;">​</a></h3>',29)),(o(),r(n,null,{default:t(()=>[c(a,{id:"mermaid-404",class:"mermaid",graph:"flowchart%20TB%0A%20%20front%5B%22frontend%22%5D%20--%20%22Tauri%20IPC%22%20--%3E%20cmd%5B%22commands%2F%3Cbr%2F%3Evalidate%2C%20dispatch%2C%20adapt%22%5D%0A%20%20cmd%20--%3E%20domain%5B%22domain%20modules%3Cbr%2F%3Ecatalog%2C%20playback%2C%20downloads%2C%3Cbr%2F%3Econnectivity%2C%20provider%20pool%2C%20providers%2C%20integrations%22%5D%0A%20%20domain%20--%3E%20infra%5B%22infrastructure%3Cbr%2F%3Edatabase%2C%20server%2C%20platform%2C%20http%2C%20clock%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=d('<h3 id="commands-is-an-adapter-layer" tabindex="-1"><code>commands/</code> is an adapter layer <a class="header-anchor" href="#commands-is-an-adapter-layer" aria-label="Permalink to &quot;`commands/` is an adapter layer&quot;">​</a></h3><p>A command reads its arguments, normalises them, calls one domain function and returns. It is not where the work happens. Three checks hold this:</p><ul><li><code>#[tauri::command]</code> appears only under <code>commands/</code>.</li><li><code>tauri::State</code> is unwrapped only under <code>commands/</code>. A domain function takes what it needs as an argument, so it can be tested without a Tauri handle.</li><li>Nothing outside <code>commands/</code> and <code>app/</code> imports <code>crate::commands</code>. A domain module that calls a command has its dependency backwards.</li></ul><p><code>app/ipc.rs</code> additionally proves at test time that every declared command is registered in the handler.</p><h3 id="the-domain-modules" tabindex="-1">The domain modules <a class="header-anchor" href="#the-domain-modules" aria-label="Permalink to &quot;The domain modules&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module</th><th>Owns</th></tr></thead><tbody><tr><td><code>catalog</code></td><td>the local anime catalogue: sync, metadata enrichment, artwork, seasons and ratings</td></tr><tr><td><code>playback</code></td><td>which episodes exist, what they are called, and which link to play</td></tr><tr><td><code>downloads</code></td><td>the queue, transfers, ffmpeg, the offline library</td></tr><tr><td><code>connectivity</code></td><td>whether each service answers, and where the connection is</td></tr><tr><td><code>providers</code></td><td>one directory per streaming source: its transport, its parsing, its mapping</td></tr><tr><td><code>provider_pool</code></td><td>choosing between providers: racing, health, circuit breaking, title matching</td></tr><tr><td><code>integrations</code></td><td>third-party services that are not streaming providers: AniList, Kitsu, AniSkip, Discord, imports and IP geolocation</td></tr></tbody></table><p>The split between <code>providers</code> and <code>provider_pool</code> is deliberate and worth keeping: an implementation of a source never decides whether it is the source that gets used.</p><h3 id="infrastructure" tabindex="-1">Infrastructure <a class="header-anchor" href="#infrastructure" aria-label="Permalink to &quot;Infrastructure&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module</th><th>Owns</th></tr></thead><tbody><tr><td><code>database</code></td><td>SQLite: schema, migrations, and read models grouped by subject</td></tr><tr><td><code>server</code></td><td>the local media proxy and image cache</td></tr><tr><td><code>platform</code></td><td>behaviour that differs per operating system, plus disk and storage accounting</td></tr><tr><td><code>app</code></td><td>Tauri setup: plugins, managed state, window, tray, command registration</td></tr></tbody></table><p>Domain modules call the database. The database holds no feature policy of its own.</p><h3 id="foundation" tabindex="-1"><code>foundation</code> <a class="header-anchor" href="#foundation" aria-label="Permalink to &quot;`foundation`&quot;">​</a></h3><p>What every other module may assume exists, and what nothing above it may reach back into:</p><table tabindex="0"><thead><tr><th>File</th><th>What it owns</th></tr></thead><tbody><tr><td><code>error.rs</code></td><td><code>AppError</code> and the stable error codes the frontend matches</td></tr><tr><td><code>http.rs</code></td><td>The one browser identity every outbound request presents</td></tr><tr><td><code>clock.rs</code></td><td>The crate&#39;s only reading of the wall clock</td></tr><tr><td><code>pattern.rs</code></td><td>Compiling the regular expressions written as literals here</td></tr></tbody></table><p>Nothing in <code>foundation</code> knows about anime, providers or downloads.</p><p>The crate root itself holds <code>lib.rs</code> and <code>main.rs</code> and nothing else. The <code>root-layout</code> and <code>clock-boundary</code> Sonar project checks report a module that lands beside them or a second <code>now()</code> anywhere in the crate.</p><h3 id="rust-tests" tabindex="-1">Rust tests <a class="header-anchor" href="#rust-tests" aria-label="Permalink to &quot;Rust tests&quot;">​</a></h3><p>Production code carries <code>#[cfg(test)] #[path = &quot;../tests/&lt;subsystem&gt;/&lt;file&gt;.rs&quot;] mod tests;</code>, and every test file lives under <code>src-tauri/src/tests/</code>, mirroring the module it covers. Small unit tests written directly against private functions may stay inline at the bottom of their file.</p><hr><h2 id="where-tests-go" tabindex="-1">Where tests go <a class="header-anchor" href="#where-tests-go" aria-label="Permalink to &quot;Where tests go&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kind</th><th>Location</th></tr></thead><tbody><tr><td>a feature&#39;s own tests</td><td><code>src/features/&lt;name&gt;/tests/</code></td></tr><tr><td>a shared package&#39;s tests</td><td><code>src/shared/&lt;package&gt;/tests/</code></td></tr><tr><td>the app layer&#39;s tests</td><td><code>src/app/tests/</code>, <code>src/app/onboarding/tests/</code></td></tr><tr><td>repository invariants: architecture, docs, locales, assets, error codes</td><td><code>scripts/sonar/project-checks.mjs</code></td></tr><tr><td>Rust</td><td><code>src-tauri/src/tests/</code></td></tr></tbody></table><p>Repository invariants are static Sonar project checks rather than executable Vitest suites: the layers point the right way, every file explains itself, both sides name the same error codes, no copy is hardcoded, and every referenced asset exists. <code>npm run sonar:checks</code> writes them as a generic issue report; <code>npm run sonar</code> imports that report into the project analysis.</p><hr><h2 id="naming" tabindex="-1">Naming <a class="header-anchor" href="#naming" aria-label="Permalink to &quot;Naming&quot;">​</a></h2><ul><li>Name a module after its subject, never after its layer. <code>episodeProgress.ts</code>, not <code>utils.ts</code>; <code>providerSelection</code>, not <code>manager</code>.</li><li>A file does not repeat a folder it already sits in: <code>player/io/playback.ts</code>, not <code>player/io/playerPlayback.ts</code>.</li><li>IO factories are <code>createX</code> or <code>installX</code>, after their lifecycle.</li><li>Components are PascalCase and named after what they render.</li><li>Every file opens with a <code>@fileoverview</code> (TypeScript) or <code>//!</code> (Rust) saying what is inside and, where it is not obvious, why it is that way. Every export in <code>io/</code> and <code>model/</code>, and every crate-public Rust item, carries a comment.</li></ul><hr><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to &quot;Enforcement&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>Enforced by</th></tr></thead><tbody><tr><td><code>shared</code> and <code>features</code> cannot import upwards</td><td><code>eslint.config.js</code></td></tr><tr><td><code>config</code> imports nothing</td><td><code>eslint.config.js</code>, <code>fileDocs</code></td></tr><tr><td><code>model/</code> is pure</td><td><code>eslint.config.js</code></td></tr><tr><td><code>ui/</code> does not touch transport</td><td><code>eslint.config.js</code></td></tr><tr><td><code>invoke()</code> only in <code>shared/ipc</code></td><td><code>eslint.config.js</code></td></tr><tr><td>no import cycles</td><td>Sonar <code>import-architecture</code></td></tr><tr><td>features reach only another feature&#39;s <code>model</code>/<code>io</code>/<code>ui</code></td><td>Sonar <code>import-architecture</code></td></tr><tr><td>tests live in <code>tests/</code> folders</td><td>Sonar <code>test-location</code></td></tr><tr><td>commands are adapters</td><td>Sonar <code>tauri-command-boundary</code></td></tr><tr><td>nothing loose at either root</td><td>Sonar <code>root-layout</code></td></tr><tr><td>assets sorted by kind</td><td>Sonar <code>root-layout</code></td></tr><tr><td>comments describe code, not its history</td><td>Sonar <code>comment-style</code></td></tr><tr><td>no em dash, no clause-joining semicolon</td><td>Sonar <code>comment-style</code></td></tr><tr><td>no query takes a list of ids</td><td>Sonar <code>anilist-policy</code></td></tr><tr><td>the metadata cache declares a ceiling</td><td>Sonar <code>anilist-policy</code></td></tr><tr><td>every command is registered</td><td><code>app/ipc.rs</code></td></tr><tr><td>one clock</td><td>Sonar <code>clock-boundary</code></td></tr><tr><td>shared packages name capabilities</td><td>Sonar <code>feature-layout</code></td></tr><tr><td>every file and public export documented</td><td>Sonar <code>file-documentation</code></td></tr><tr><td>error codes match across the boundary</td><td>Sonar <code>error-contract</code></td></tr></tbody></table><p>Generate all repository-specific findings with <code>npm run sonar:checks</code>, then run the complete local analysis as described under <a href="./SonarQube">SonarQube</a>.</p>',28))])}const v=i(p,[["render",u]]);export{k as __pageData,v as default};
